SELECT s.id, COALESCE(s.full_name_english, s.full_name_amharic, s.username) AS name, s.phone, s.username, (SELECT STRING_AGG(sess.name || ' (ID: ' || sess.id || ')', ', ' ORDER BY sess.id) FROM sessions sess WHERE sess.id IN (6,7,8,9) AND sess.id NOT IN (SELECT att.session_id FROM attendance att WHERE att.student_id = s.id)) AS missed_sessions, (SELECT STRING_AGG(sess.name || ' (ID: ' || sess.id || ')', ', ' ORDER BY sess.id) FROM sessions sess WHERE sess.id IN (6,7,8,9) AND sess.id IN (SELECT att.session_id FROM attendance att WHERE att.student_id = s.id)) AS attended_sessions, (SELECT COUNT(*) FROM sessions sess WHERE sess.id IN (6,7,8,9) AND sess.id NOT IN (SELECT att.session_id FROM attendance att WHERE att.student_id = s.id)) AS missed_count FROM students s WHERE s.phone IN ('0953440667', '0924370071', '0910681906');

